// Extraire les données du webhook
const data = $input.first().json.body || $input.first().json;

console.log('Données maintenance email reçues:', JSON.stringify(data));

const maintenanceNumber = data.maintenance_number || data.maintenanceNumber || 'N/A';
const clientName = data.client_name || data.clientName || 'Client';
const device = data.device || '';
const kind = data.kind || 'technician';

// URL HTML du document (accessible via réseau Docker)
// Aligné sur le pattern facture/devis: URL interne nitek_app
const htmlUrl = `http://nitek_app:8000/api/maintenances/${data.maintenance_id}/print?kind=${encodeURIComponent(kind)}`;

const email = data.email || '';

return [{
  json: {
    maintenanceNumber,
    clientName,
    device,
    kind,
    htmlUrl,
    email
  }
}];

// Récupérer les données précédentes et le fichier PDF
const previousData = $('Extract Data').first().json;

const maintenanceNumber = previousData.maintenanceNumber;
const clientName = previousData.clientName;
const email = previousData.email;
const device = previousData.device;
const kind = previousData.kind;

const subject = `Maintenance ${maintenanceNumber} (${kind})`;

const htmlBody = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .container { max-width: 600px; margin: 0 auto; padding: 20px; }
    .header { background: #2c3e50; color: white; padding: 20px; text-align: center; }
    .content { padding: 20px; background: #f9f9f9; }
    .box { background: white; padding: 15px; border-radius: 5px; margin: 15px 0; }
    .footer { text-align: center; padding: 20px; color: #666; font-size: 12px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>GeekTechnologie</h1>
    </div>
    <div class="content">
      <p>Bonjour <strong>${clientName}</strong>,</p>
      <p>Veuillez trouver ci-joint votre document de maintenance.</p>

      <div class="box">
        <p><strong>Référence :</strong> ${maintenanceNumber}</p>
        <p><strong>Type de document :</strong> ${kind}</p>
        ${device ? `<p><strong>Appareil :</strong> ${device}</p>` : ''}
      </div>

      <p style="margin-top: 20px;">Pour toute question, n'hésitez pas à nous contacter.</p>
      <p>Cordialement,<br><strong>L'équipe GeekTechnologie</strong></p>
    </div>
    <div class="footer">
      <p>GeekTechnologie - Votre partenaire technologique</p>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    to: email,
    subject: subject,
    html: htmlBody
  }
}];
